components.css:
.ds-primary{min-height:46px;border-radius:12px;padding:12px 20px;font-size:14px;font-weight:550;border:1px solid transparent;white-space:nowrap;cursor:pointer;transition:background 180ms,border-color 180ms,box-shadow 180ms,transform 180ms;background: #202127;
  border-color: #202127;
  color: white;
  box-shadow: 0 2px 4px #20212710;}.ds-primary:hover:not(:disabled){background: #35363e;
  border-color: #35363e;
  box-shadow: 0 5px 12px #20212718;}.ds-primary:focus-visible{outline:2px solid var(--accent,#315cc7);outline-offset:3px}.ds-primary:active:not(:disabled){transform:scale(.975);transition-duration:80ms}.ds-primary:disabled{opacity:.55;cursor:not-allowed} @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}

.ds-text{min-height: 44px;
  color: var(--accent,#315cc7);
  background: transparent;
  border: 0;
  font-size: 13px;
  font-weight: 550;
  padding: 8px;}.ds-text:hover{text-decoration:underline}.ds-text:focus-visible{outline:2px solid var(--accent,#315cc7);outline-offset:3px}.ds-text:active{transform:scale(.975)} @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}

.ds-field{display: block;
  font-size: 13px;
  font-weight: 550;
  color: #42454f;}.ds-field textarea{display:block;width:100%;margin-top:10px;padding:14px 16px;color:var(--text,#1d1d1f);background:#f6f6f9;border:1px solid #e9e9ef;border-radius:12px;font-size:14px;font-weight:400;min-height:216px;line-height:1.8;resize:vertical;transition:background 180ms,border-color 180ms,box-shadow 180ms}.ds-field textarea:focus{background:white;border-color:#b4c4ee;box-shadow:0 0 0 4px #315cc70a}.ds-field textarea:focus-visible{outline:2px solid var(--accent,#315cc7);outline-offset:3px} @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}

.ds-nav{position: relative;
  display: flex;
  align-items: center;
  width: 316px;
  min-height: 48px;
  padding: 4px;
  border: 1px solid #e2e3e9;
  background: #eaeaf0;
  border-radius: 28px;}.ds-nav button{z-index: 1;
  position: relative;
  flex: 1;
  min-height: 40px;
  padding: 0 12px;
  border: 0;
  border-radius: 24px;
  color: var(--muted,#62646b);
  background: transparent;
  font-size: 14px;
  white-space: nowrap;}.ds-nav button:hover{color: var(--text,#1d1d1f);}.ds-active{color: var(--text,#1d1d1f);
  font-weight: 600;}.ds-track{position: absolute;
  inset: 4px auto 4px 4px;
  width: calc((100% - 8px) / 3);
  border-radius: 24px;
  background: white;
  box-shadow:
    0 2px 7px #2123380f,
    0 1px 2px #2123380a;
  pointer-events: none;
  transition: transform 260ms var(--ease-out,cubic-bezier(.16,1,.3,1));}.ds-track{transform:translateX(100%)}.ds-nav button:focus-visible{outline:2px solid var(--accent,#315cc7);outline-offset:3px} @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}

.ds-badge{font-size: 12px;
  padding: 3px 8px;
  background: #f1f4f8;
  border: 1px solid #dce3ed;
  border-radius: 4px;
  color: #4f6078;
  overflow-wrap: anywhere;}.ds-badge{color: #2754a4;
  background: var(--accent-light,#edf2ff);
  border-color: #d2dff5;} @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}

.ds-panel{background: var(--surface,#fff);
  border: 1px solid #ffffff;
  border-radius: 22px;
  padding: 32px;
  box-shadow:
    0 8px 32px #272b4506,
    0 1px 2px #272b4508;}.ds-panel{color:var(--text,#1d1d1f)}.ds-panel h2{font-size:17px;font-weight:600;margin:0 0 12px}.ds-panel p{font-size:14px;line-height:1.9;margin:0} @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}

.ds-rating{background: var(--surface,#fff);
  border: 1px solid #e4e5ee;
  border-radius: 16px;
  padding: 20px 12px;
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 7px;
  color: var(--text,#1d1d1f);
  box-shadow: 0 2px 5px #20212704;}.ds-rating strong{font-size:14px;color:var(--accent,#315cc7)}.ds-rating span{font-size:12px;color:var(--muted,#62646b)}.ds-rating:hover:not(:disabled){background: #f1f5fc;
  border-color: #8299bc;}.ds-rating:focus-visible{outline:2px solid var(--accent,#315cc7);outline-offset:3px}.ds-rating:active:not(:disabled){transform:scale(.975);transition-duration:80ms}.ds-rating:disabled{opacity:.55} @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}
